const item = $input.first();
const agentData = $('Estrai JSON dall\'agente').first().json;
const sessionId = agentData.session_id;
const objectName = agentData.object_name;
const seed = agentData.seed;

// Il nodo comfyui mason276752 restituisce le immagini come binary
// La chiave binary può essere 'data', 'image', o il filename
const binaryKeys = Object.keys(item.binary ?? {});
console.log('Binary keys disponibili da FLUX:', JSON.stringify(binaryKeys));
console.log('JSON da FLUX:', JSON.stringify(item.json).substring(0, 400));

if (binaryKeys.length === 0) {
  throw new Error(`Nessun binary trovato nell output FLUX. JSON: ${JSON.stringify(item.json).substring(0, 300)}`);
}

const binaryKey = binaryKeys[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Image = buffer.toString('base64');

const dataUri = base64Image;

console.log(`Immagine convertita: ${Math.round(buffer.length / 1024)}KB, key: ${binaryKey}`);

return [{ json: {
  image_base64: dataUri,
  session_id: sessionId,
  object_name: objectName,
  seed: seed
} }];

// Polling del GLB legato a QUESTA esecuzione (tramite prompt_id di ComfyUI)
const history   = $input.first().json;
const agentData = $('Estrai JSON dall\'agente').first().json;
const promptId  = $('Comfy3D - Meshy').first().json.prompt_id;

if (!promptId) {
  throw new Error('prompt_id mancante nella risposta di Comfy3D - Meshy');
}

let attempts;
try {
  attempts = ($('If').first().json._attempts ?? 0) + 1;
} catch (e) {
  attempts = 1;
}
const MAX_ATTEMPTS = 15;

// /api/history/{prompt_id} restituisce {} finché il prompt non è completato
const entry = history[promptId];

if (entry?.status?.status_str === 'error') {
  throw new Error(`ComfyUI: esecuzione fallita per prompt ${promptId}`);
}

// Tutti i GLB prodotti da questo prompt (i SaveGLB sono due: 11 e 12)
const glbs = [];
for (const out of Object.values(entry?.outputs ?? {})) {
  const meshArray = out?.meshes || out?.['3d'] || [];
  for (const mesh of meshArray) {
    if (mesh.filename?.endsWith('.glb')) glbs.push(mesh);
  }
}
// Come nella versione precedente, si usa l'ultimo trovato
const glb = glbs.length ? glbs[glbs.length - 1] : null;

// GLB di questa richiesta non ancora pronto
if (!glb) {
  if (attempts >= MAX_ATTEMPTS) {
    throw new Error(`Timeout: nessun GLB per prompt ${promptId} dopo ${MAX_ATTEMPTS} tentativi (${MAX_ATTEMPTS * 30}s)`);
  }
  return [{ json: {
    _ready: false,
    _attempts: attempts,
    prompt_id: promptId,
    session_id: agentData.session_id,
    object_name: agentData.object_name
  }}];
}

// GLB pronto
const host = "192.168.1.27";
const port = 8000;
const glbUrl = `http://${host}:${port}/view?filename=${encodeURIComponent(glb.filename)}&type=${glb.type || 'output'}&subfolder=${encodeURIComponent(glb.subfolder || '3d')}`;

return [{ json: {
  _ready: true,
  _attempts: attempts,
  status: "ready",
  glb_url: glbUrl,
  prompt_id: promptId,
  object_name: agentData.object_name,
  session_id: agentData.session_id,
  message: "Oggetto generato con successo!"
}}];

